document.addEventListener('DOMContentLoaded',()=>{const isLocalFile=window.location.protocol==='file:';if(!isLocalFile){const manifestLink=document.createElement('link');manifestLink.rel='manifest';const isInArticles=window.location.pathname.includes('/articles/');manifestLink.href=isInArticles?'../manifest.json':'manifest.json';document.head.appendChild(manifestLink);}
const header=document.querySelector('.site-header');const navToggle=document.querySelector('.nav-toggle');const primaryNav=document.querySelector('#primary-nav');const navOverlay=document.createElement('div');navOverlay.classList.add('nav-overlay');document.body.insertBefore(navOverlay,document.body.firstChild);window.addEventListener('scroll',()=>{if(window.scrollY>50){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}});navToggle.addEventListener('click',()=>{const isExpanded=navToggle.getAttribute('aria-expanded')==='true';toggleNav(!isExpanded);});navOverlay.addEventListener('click',()=>{toggleNav(false);});primaryNav.querySelectorAll('a').forEach(link=>{link.addEventListener('click',(e)=>{toggleNav(false);});});function toggleNav(show){navToggle.setAttribute('aria-expanded',show);primaryNav.setAttribute('data-visible',show);if(show){navOverlay.classList.add('active');document.body.style.overflow='hidden';}else{navOverlay.classList.remove('active');document.body.style.overflow='';}}
const observerOptions={root:null,rootMargin:'0px',threshold:0.15};const revealObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},observerOptions);document.querySelectorAll('.reveal-section, .reveal-item').forEach(el=>{revealObserver.observe(el);});const filterBtns=document.querySelectorAll('.filter-btn');const galleryItems=document.querySelectorAll('.gallery-item');const loadMoreBtn=document.getElementById('load-more');const savedFilter=localStorage.getItem('galleryFilter')||'all';applyFilter(savedFilter);updateActiveButton(savedFilter);filterBtns.forEach(btn=>{btn.addEventListener('click',()=>{const filterValue=btn.getAttribute('data-filter');applyFilter(filterValue);updateActiveButton(filterValue);localStorage.setItem('galleryFilter',filterValue);});});function applyFilter(filter){let visibleCount=0;galleryItems.forEach(item=>{const category=item.getAttribute('data-category');if(filter==='all'||category===filter){item.classList.remove('hidden');item.style.display='block';visibleCount++;}else{item.classList.add('hidden');item.style.display='none';}});if(loadMoreBtn){loadMoreBtn.style.display=visibleCount>8?'inline-block':'none';}}
function updateActiveButton(filter){filterBtns.forEach(btn=>{if(btn.getAttribute('data-filter')===filter){btn.classList.add('active');}else{btn.classList.remove('active');}});}
if(loadMoreBtn){loadMoreBtn.addEventListener('click',()=>{alert('In a real implementation, this would load the next page of items from the server or JSON file.');});}
const lightbox=document.getElementById('lightbox');const lightboxImg=document.getElementById('lightbox-img');const lightboxClose=document.getElementById('lightbox-close');const prevBtn=document.getElementById('lightbox-prev');const nextBtn=document.getElementById('lightbox-next');let currentImageIndex=0;const getVisibleItems=()=>Array.from(document.querySelectorAll('.gallery-item:not(.hidden) img'));galleryItems.forEach(item=>{const img=item.querySelector('img');img.addEventListener('click',()=>{const visibleImages=getVisibleItems();currentImageIndex=visibleImages.indexOf(img);openLightbox(img.src);});item.addEventListener('keydown',(e)=>{if(e.key==='Enter'){img.click();}});});function openLightbox(src){lightboxImg.src=src;lightbox.classList.add('active');lightbox.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';lightboxClose.focus();}
function closeLightbox(){lightbox.classList.remove('active');lightbox.setAttribute('aria-hidden','true');document.body.style.overflow='';}
function showNextImage(){const visibleImages=getVisibleItems();currentImageIndex=(currentImageIndex+1)%visibleImages.length;lightboxImg.src=visibleImages[currentImageIndex].src;}
function showPrevImage(){const visibleImages=getVisibleItems();currentImageIndex=(currentImageIndex-1+visibleImages.length)%visibleImages.length;lightboxImg.src=visibleImages[currentImageIndex].src;}
if(lightboxClose)lightboxClose.addEventListener('click',closeLightbox);if(lightbox){lightbox.addEventListener('click',(e)=>{if(e.target===lightbox)closeLightbox();});}
if(nextBtn){nextBtn.addEventListener('click',(e)=>{e.stopPropagation();showNextImage();});}
if(prevBtn){prevBtn.addEventListener('click',(e)=>{e.stopPropagation();showPrevImage();});}
document.addEventListener('keydown',(e)=>{if(!lightbox)return;if(!lightbox.classList.contains('active'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowRight')showNextImage();if(e.key==='ArrowLeft')showPrevImage();});const quoteForm=document.getElementById('quote-form');const formStatus=document.getElementById('form-status');if(quoteForm){const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;const inputs=quoteForm.querySelectorAll('input[required], textarea[required]');function validateField(input){const formGroup=input.parentElement;let isFieldValid=true;if(input.type==='email'){isFieldValid=emailRegex.test(input.value.trim());}else{isFieldValid=input.value.trim().length>0;}
if(!isFieldValid){formGroup.classList.add('error');formGroup.classList.remove('valid');input.setAttribute('aria-invalid','true');return false;}else{formGroup.classList.remove('error');formGroup.classList.add('valid');input.setAttribute('aria-invalid','false');return true;}}
inputs.forEach(input=>{input.addEventListener('blur',()=>{validateField(input);});input.addEventListener('input',()=>{const formGroup=input.parentElement;formGroup.classList.remove('error');input.setAttribute('aria-invalid','false');});});quoteForm.addEventListener('submit',(e)=>{e.preventDefault();let isFormValid=true;inputs.forEach(input=>{if(!validateField(input)){isFormValid=false;}});if(isFormValid){const btn=quoteForm.querySelector('button[type="submit"]');const originalText=btn.innerText;const formData=new FormData(quoteForm);const scriptURL='https://script.google.com/macros/s/AKfycbzzQfPvMB4Nv1ART_8U1gsi0fHrO7xo-OTkPf7VG2LtUle12CfrEAFIYfqRH8RiVmOjhw/exec';btn.innerText='Sending...';btn.disabled=true;fetch(scriptURL,{method:'POST',body:formData,mode:'no-cors'}).then(response=>{formStatus.textContent='Message sent successfully! We will be in touch soon.';formStatus.style.color='green';quoteForm.reset();btn.innerText=originalText;btn.disabled=false;}).catch(error=>{console.error('Error!',error.message);formStatus.textContent='Oops! There was an error sending your message. Please try again or email directly.';formStatus.style.color='red';btn.innerText=originalText;btn.disabled=false;});}});}
const yearEl=document.getElementById('year');if(yearEl)yearEl.textContent=new Date().getFullYear();const labelNewoIframes=()=>{document.querySelectorAll('iframe[name="newo-chat-frame"]:not([title])').forEach(el=>{el.setAttribute('title','Chat window');});document.querySelectorAll('iframe[name="newo-chat-toggler-frame"]:not([title])').forEach(el=>{el.setAttribute('title','Open chat');});};labelNewoIframes();const newoObserver=new MutationObserver(labelNewoIframes);newoObserver.observe(document.body,{childList:true,subtree:true});(function(){let newoLoaded=false;const interactionEvents=['scroll','mousemove','touchstart','keydown','pointerdown'];function loadNewoChat(){if(newoLoaded)return;newoLoaded=true;interactionEvents.forEach(e=>window.removeEventListener(e,loadNewoChat,true));const s=document.createElement('script');s.src='https://static.newo.ai/newo-chat/web-chat.js';s.setAttribute('name','web-chat');s.setAttribute('data-client-secret','e25d408e-22c9-4ff5-92f1-f32233d19e76');document.body.appendChild(s);}
interactionEvents.forEach(e=>window.addEventListener(e,loadNewoChat,{once:true,passive:true,capture:true}));}());});